function setupShowroomControls(canvas){canvas.style.touchAction='none';canvas.style.cursor='grab';canvas.addEventListener('pointerdown',event=>{if(!showroomMode||event.button!==0)return;showroomOrbit.dragging=true;showroomOrbit.pointerId=event.pointerId;showroomOrbit.lastX=event.clientX;canvas.style.cursor='grabbing';canvas.setPointerCapture(event.pointerId);});canvas.addEventListener('pointermove',event=>{if(!showroomOrbit.dragging||event.pointerId!==showroomOrbit.pointerId)return;const delta=event.clientX-showroomOrbit.lastX;showroomCar.rotation.y-=delta*.012;showroomOrbit.lastX=event.clientX;});const stop=event=>{if(event.pointerId!==showroomOrbit.pointerId)return;showroomOrbit.dragging=false;showroomOrbit.pointerId=null;canvas.style.cursor='grab';};canvas.addEventListener('pointerup',stop);canvas.addEventListener('pointercancel',stop);canvas.addEventListener('lostpointercapture',stop);}
