  const points=[[-100,0],[-92,-27],[-76,-48],[-52,-60],[-25,-58],[-2,-49],[22,-53],[49,-56],[73,-43],[91,-20],[95,7],[84,31],[63,49],[37,57],[12,51],[-10,43],[-34,52],[-59,49],[-80,35],[-94,17]].map(([x,z])=>new THREE.Vector3(x,0,z));
