 const ribbon=(start,end,offset,halfWidth,material,y=.05,segments=1)=>{const verts=[],indices=[];for(let j=0;j<=segments;j++){const t=start+(end-start)*j/segments,p=trackPoint(t,offset-halfWidth),q=trackPoint(t,offset+halfWidth);verts.push(p.x,y,p.z,q.x,y,q.z);if(j<segments){const a=j*2;indices.push(a,a+1,a+2,a+1,a+3,a+2);}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setIndex(indices);g.computeVertexNormals();const m=new THREE.Mesh(g,material);m.material.side=THREE.DoubleSide;roadGroup.add(m);return m;};
