 ribbon(0,1,0,trackWidth/2,asphalt,0,480);
 ribbon(0,1,-10.8,.2,edgeMat,.075,480);ribbon(0,1,10.8,.2,edgeMat,.075,480);
 // Alternating pit-stop kerbs sit fully inside the constant-width road ribbon.
 for(const side of [-1,1]){const pieces=[];for(let i=0;i<160;i++)pieces.push([i/160,(i+1)/160,((i>>1)%2)?0:1]);segmentsBand(side*10.0,.85,pieces,[white,red],.09);}
