  const bridge=new THREE.Group(),bridgeMat=new THREE.MeshStandardMaterial({color:'#59656b',metalness:.3,roughness:.55}),supportMat=new THREE.MeshStandardMaterial({color:'#778184',metalness:.25});const deck=new THREE.Mesh(new THREE.BoxGeometry(30,.65,13),bridgeMat);deck.position.set(-46,5.5,7);bridge.add(deck);for(const z of [1,13]){const rail=new THREE.Mesh(new THREE.BoxGeometry(30,.7,.35),new THREE.MeshStandardMaterial({color:'#e6e2d5'}));rail.position.set(-46,6.15,z);bridge.add(rail);}for(const x of [-57,-35]){const pier=new THREE.Mesh(new THREE.BoxGeometry(1,5,.8),supportMat);pier.position.set(x,2.5,7);bridge.add(pier);}roadGroup.add(bridge);
