 const base=new THREE.Mesh(new THREE.BoxGeometry(42,5,9),buildingMat);base.position.set(-46,2.5,-1);roadGroup.add(base);const roof=new THREE.Mesh(new THREE.BoxGeometry(44,.55,10),roofMat);roof.position.set(-46,5.25,-1);roadGroup.add(roof);
