function makeCar(color='#f04b31',hero=false){const car=makeHeroCar(color);car.scale.setScalar(.86);return car;}
function onResize(){if(!renderer)return;camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();if(showroomCamera){showroomCamera.aspect=innerWidth/innerHeight;showroomCamera.updateProjectionMatrix();}renderer.setSize(innerWidth,innerHeight);}
function signedTrackGap(a,b){return ((a-b+trackLength/2+trackLength)%trackLength)-trackLength/2;}
